1955: inline std::vector<line_reference> group_128b_references(
1956:     const std::vector<sector_access> &accesses) {
1957:   std::map<uint64_t, uint8_t> grouped;
1958:   for (const sector_access &access : accesses) {
1959:     const uint64_t line = access.address & ~(kLogicalLineBytes - 1);
1960:     const unsigned sector = (access.address >> 5) & (kSectorsPerLogicalLine - 1);
1961:     const uint8_t canonical_mask = access.sector_mask
1962:                                        ? access.sector_mask
1963:                                        : static_cast<uint8_t>(1U << sector);
1964:     assert((canonical_mask & ~0xFU) == 0);
1965:     grouped[line] |= canonical_mask;
1966:   }
1967:   std::vector<line_reference> result;
1968:   result.reserve(grouped.size());
1969:   for (const auto &entry : grouped) {
1970:     result.push_back({entry.first, entry.second});
1971:   }
1972:   return result;
1973: }
