3357:                              : m_dtc_l1_oo_frontend->admit(uid);
3358:     if (!admitted) {
3359:       stall_reason = BK_CONF;
3360:       access_type = G_MEM_LD;
3361:       return false;
3362:     }
3363:     m_dtc_l1_oo_pib.push_back({inst, dtc_l1_io_line_references(inst), 0});
