3460: void ldst_unit::dtc_l1_oo_issue_lower_requests() {
3461:   if (!dtc_l1_paper_oo_active()) return;
3462:   const unsigned long long cycle =
3463:       m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle;
3464:   if (!m_dtc_l1_oo_lower_create_queue.empty() &&
3465:       (!dtc_l1_finite_service_active() || m_dtc_service_create.available(cycle)) &&
3466:       m_core->get_gpu()->dtc_l1_try_acquire_lower_request()) {
3467:     if (dtc_l1_finite_service_active()) m_dtc_service_create.commit(cycle);
3468:     const dtc_l1_oo_lower_candidate candidate =
3469:         m_dtc_l1_oo_lower_create_queue.front();
3470:     dtc_l1_oo_pib_entry *entry = dtc_l1_oo_find_entry(candidate.inst_uid);
3471:     assert(entry);
3472:     mem_access_byte_mask_t byte_mask;
3473:     mem_access_sector_mask_t sector_mask;
3474:     uint64_t request_address = candidate.line_address;
3475:     unsigned request_size = dtc_l1::kLogicalLineBytes;
3476:     if (dtc_l1_sector_oo_active()) {
3477:       assert(candidate.sector_mask && !(candidate.sector_mask &
3478:                                          (candidate.sector_mask - 1)) &&
3479:              !(candidate.sector_mask & ~0xFU));
3480:       unsigned sector = 0;
3481:       while (!(candidate.sector_mask & (1U << sector))) ++sector;
3482:       request_address += sector * 32;
3483:       request_size = 32;
3484:       sector_mask.set(sector);
3485:       for (unsigned byte = sector * 32; byte < (sector + 1) * 32; ++byte)
3486:         byte_mask.set(byte);
3487:     } else {
3488:       byte_mask.set();
3489:       sector_mask.set();
3490:     }
3491:     mem_access_t lower_read(GLOBAL_ACC_R, request_address, request_size, false,
3492:                             entry->inst.get_warp_active_mask(), byte_mask,
3493:                             sector_mask, m_memory_config->gpgpu_ctx);
3494:     mem_fetch *mf = m_mf_allocator->alloc(entry->inst, lower_read, cycle);
3495:     const bool inserted = m_dtc_l1_oo_inflight
3496:                               .emplace(mf->get_request_uid(),
3497:                                        dtc_l1_oo_inflight{candidate.physical,
3498:                                                            candidate.line_address,
3499:                                                            candidate.inst_uid,
3500:                                                            candidate.sector_mask})
3501:                               .second;
3502:     assert(inserted && "OO request UID must remain unique while live");
3503:     m_dtc_l1_oo_lower_issue_queue.push_back(mf);
3504:     m_dtc_l1_oo_lower_create_queue.pop_front();
3505:     ++m_dtc_l1_oo_lower_created;
3506:   }
3507:   // Frozen lower issue width: one request per SM/cycle.
3508:   if (!m_dtc_l1_oo_lower_issue_queue.empty()) {
3509:     mem_fetch *mf = m_dtc_l1_oo_lower_issue_queue.front();
3510:     if ((!dtc_l1_finite_service_active() || m_dtc_service_inject.available(cycle)) &&
3511:         !m_icnt->full(mf->size(), false)) {
3512:       if (dtc_l1_finite_service_active()) m_dtc_service_inject.commit(cycle);
3513:       mf->set_status(IN_ICNT_TO_MEM, cycle);
3514:       m_icnt->push(mf);
3515:       m_dtc_l1_oo_lower_issue_queue.pop_front();
3516:       ++m_dtc_l1_oo_lower_issued;
3517:     }
3518:   }
