3521: bool ldst_unit::dtc_l1_oo_consume_response(mem_fetch *mf) {
3522:   if (!dtc_l1_paper_oo_active()) return false;
3523:   auto it = m_dtc_l1_oo_inflight.find(mf->get_request_uid());
3524:   if (it == m_dtc_l1_oo_inflight.end() && mf->get_original_mf())
3525:     it = m_dtc_l1_oo_inflight.find(
3526:         mf->get_original_mf()->get_request_uid());
3527:   if (it == m_dtc_l1_oo_inflight.end()) return false;
3528:   dtc_l1_oo_inflight &record = it->second;
3529:   const uint64_t aligned_address =
3530:       mf->get_addr() & ~(dtc_l1::kLogicalLineBytes - 1);
3531:   const unsigned sector =
3532:       static_cast<unsigned>((mf->get_addr() - record.line_address) / 32);
3533:   if (mf->get_is_write() || aligned_address != record.line_address ||
3534:       !dtc_l1::response_sector_is_new(record.expected_sector_mask,
3535:                                      record.response_sector_mask, sector)) {
3536:     assert(false && "OO response identity/address mismatch");
3537:   }
3538:   record.response_sector_mask |= static_cast<uint8_t>(1U << sector);
3539:   mem_fetch *original = mf->get_original_mf();
3540:   const bool request_complete =
3541:       record.response_sector_mask == record.expected_sector_mask;
3542:   if (request_complete) {
3543:     if (dtc_l1_sector_oo_active())
3544:       m_dtc_l1_sector_frontend->complete_sector(record.physical, sector);
3545:     else
3546:       m_dtc_l1_oo_frontend->complete(record.physical);
3547:     m_core->get_gpu()->dtc_l1_complete_lower_request();
3548:     m_dtc_l1_oo_inflight.erase(it);
3549:     ++m_dtc_l1_oo_lower_responses;
3550:   }

3593: bool ldst_unit::dtc_l1_oo_writeback_ready() {
3594:   const uint64_t service_cycle = m_core->get_gpu()->global_cycle();
3595:   if (dtc_l1_finite_service_active() &&
3596:       !m_dtc_service_retire.available(service_cycle)) return false;
3597:   if (!dtc_l1_paper_oo_active()) return false;
3598:   uint64_t uid = 0;
3599:   const bool ready = dtc_l1_oo_select_ready(&uid);
3600:   if (!ready) return false;
3601:   dtc_l1_oo_pib_entry *entry = dtc_l1_oo_find_entry(static_cast<unsigned>(uid));
3602:   assert(entry);
3603:   const unsigned long long cycle =
3604:       m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle;
3605:   if (entry->operation != dtc_l1_m4_operation::CACHEABLE_LOAD) {
3606:     assert(entry->source_completed && entry->references.empty());
3607:     const bool retired_ok = dtc_l1_sector_oo_active()
3608:                                 ? m_dtc_l1_sector_frontend->retire_ready_uid(
3609:                                       cycle, uid)
3610:                                 : m_dtc_l1_oo_frontend->retire_ready_uid(cycle,
3611:                                                                          uid);
3612:     assert(retired_ok);
3613:     if (dtc_l1_finite_service_active()) m_dtc_service_retire.commit(service_cycle);
3614:     for (auto it = m_dtc_l1_oo_pib.begin(); it != m_dtc_l1_oo_pib.end(); ++it)
3615:       if (it->inst.get_uid() == uid) {
3616:         m_dtc_l1_oo_pib.erase(it);
3617:         break;
3618:       }
3619:     ++m_dtc_l1_m4_observation_retires;
3620:     m_dtc_l1_oo_out_of_order_retires =
3621:         dtc_l1_sector_oo_active()
3622:             ? m_dtc_l1_sector_frontend->out_of_order_retires()
3623:             : m_dtc_l1_oo_frontend->out_of_order_retires();
3624:     return true;
3625:   }
3626:   if (!dtc_l1_service_collect(entry->service, entry->references)) return false;
3627:   m_next_wb = entry->inst;
3628:   if (!m_operand_collector->writeback(m_next_wb)) {
3629:     ++m_dtc_l1_oo_ready_but_wb_blocked_cycles;
3630:     m_next_wb.clear();
3631:     return false;
3632:   }
3633:   // Mirror IO: readiness becomes a non-retryable ledger transition only on
3634:   // the successful shared-operand-collector grant.
3635:   dtc_l1_r4c1_record_ready(entry->inst,
3636:                             static_cast<unsigned>(entry->next_reference),
3637:                             static_cast<unsigned>(entry->references.size()), "OO");
3638:   const unsigned dependencies =
3639:       dtc_l1_r4c3_registered_dependencies(entry->inst);
3640:   dtc_l1_service_retired(entry->service);
3641:   dtc_l1_oo_complete_instruction(entry->inst, dependencies);
3642:   uint64_t retired = 0;
3643:   const bool retired_ok = dtc_l1_sector_oo_active()
3644:                               ? m_dtc_l1_sector_frontend->retire_ready_uid(
3645:                                     cycle, uid)
3646:                               : m_dtc_l1_oo_frontend->retire_ready_uid(cycle,
3647:                                                                        uid);
3648:   assert(retired_ok);
3649:   for (auto it = m_dtc_l1_oo_pib.begin(); it != m_dtc_l1_oo_pib.end(); ++it) {
3650:     if (it->inst.get_uid() == uid) {
3651:       m_dtc_l1_oo_pib.erase(it);
3652:       break;
3653:     }
3654:   }
3655:   m_dtc_l1_oo_out_of_order_retires =
3656:       dtc_l1_sector_oo_active()
3657:           ? m_dtc_l1_sector_frontend->out_of_order_retires()
3658:           : m_dtc_l1_oo_frontend->out_of_order_retires();
3659:   m_next_wb.clear();
3660:   return true;
3661: }
