3023: bool ldst_unit::dtc_l1_service_collect(
3024:     dtc_l1::service_entry &service,
3025:     const std::vector<dtc_l1::line_reference> &references) {
3026:   if (!dtc_l1_finite_service_active()) return true;
3027:   const uint64_t cycle = m_core->get_gpu()->global_cycle();
3028:   if (service.ready_cycle == UINT64_MAX) {
3029:     unsigned sectors = 0;
3030:     for (const auto &reference : references)
3031:       sectors += __builtin_popcount(reference.sector_mask);
3032:     service.observe_ready(cycle, sectors);
3033:     if (m_config->dtc_l1_progressive_wakeup) ++m_dtc_progressive_collectable_entries;
3034:   }
3035:   const unsigned before = service.sectors_left;
3036:   const bool collected = service.collect(cycle, m_dtc_service_collect);
3037:   m_dtc_service_collected_sectors += before - service.sectors_left;
3038:   return collected;
3039: }
