1198: void baseline_cache::bandwidth_management::use_data_port(
1199:     mem_fetch *mf, enum cache_request_status outcome,
1200:     const std::list<cache_event> &events) {
1201:   unsigned data_size = mf->get_data_size();
1202:   unsigned port_width = m_config.m_data_port_width;
1203:   switch (outcome) {
1204:     case HIT: {
1205:       unsigned data_cycles =
1206:           data_size / port_width + ((data_size % port_width > 0) ? 1 : 0);
1207:       m_data_port_occupied_cycles += data_cycles;
1208:     } break;
1209:     case HIT_RESERVED:
1210:     case MISS: {
1211:       // the data array is accessed to read out the entire line for write-back
1212:       // in case of sector cache we need to write bank only the modified sectors
1213:       cache_event ev(WRITE_BACK_REQUEST_SENT);
1214:       if (was_writeback_sent(events, ev)) {
1215:         unsigned data_cycles = ev.m_evicted_block.m_modified_size / port_width;
1216:         m_data_port_occupied_cycles += data_cycles;
1217:       }
1218:     } break;
1219:     case SECTOR_MISS:
1220:     case RESERVATION_FAIL:
1221:       // Does not consume any port bandwidth
1222:       break;
1223:     default:
1224:       assert(0);
1225:       break;
1226:   }
1227: }
